 async bindConfig(d){if(!$('co-zone-form'))return;const o=await API.request('/cobalt/options'),z=$('co-zone-form'),l=$('co-location-form');z.elements.project_id.innerHTML=o.projects.map(p=>`<option value="${p.id}">${esc(I18n.translate(p.name,true))}</option>`).join('');const warehouses=()=>{z.elements.warehouse_id.innerHTML=o.warehouses.filter(w=>w.project_id===z.elements.project_id.value).map(w=>`<option value="${w.id}">${esc(I18n.translate(w.name,true))}</option>`).join('');};warehouses();z.elements.project_id.onchange=warehouses;for(const [form,kind,rows] of [[z,'zones',d.zones],[l,'locations',d.locations]]){form.elements.edit_id.onchange=()=>{const row=rows.find(r=>r.id===form.elements.edit_id.value);if(row){form.dataset.expectedVersion=row.version;if(kind==='zones'){form.elements.project_id.value=row.project_id;warehouses();}for(const [k,v] of Object.entries(row))if(form.elements[k]&&k!=='edit_id'){if(k==='active')form.elements[k].checked=v;else form.elements[k].value=v;}for(const k of kind==='zones'?['project_id','warehouse_id']:['zone_id'])form.elements[k].disabled=true;}else{delete form.dataset.expectedVersion;form.reset();for(const k of kind==='zones'?['project_id','warehouse_id']:['zone_id'])form.elements[k].disabled=false;}};form.onsubmit=async e=>{e.preventDefault();const id=form.elements.edit_id.value,row=rows.find(r=>r.id===id),body={};for(const input of form.elements)if(input.name&&!['edit_id'].includes(input.name))body[input.name]=input.name==='active'?input.checked:['x','y','width','height'].includes(input.name)?Number(input.value):input.value;if(row)body.version=Number(form.dataset.expectedVersion||row.version);if(!await OperationConfirm.ask({title:this.t('保存位置配置','Save Location Configuration'),rows:[[this.t('编号','Code'),body.code]],note:body.reason}))return;try{await API.request('/cobalt/stock/'+kind+(id?'/'+id:''),{method:'POST',body});ProductContext.dirty=false;await this.map();}catch(e){$('co-stock-error').textContent=this.error(e);}};}},
